param([string]$Compiler = 'C:/msys64/ucrt64/bin/gcc.exe')
$ErrorActionPreference = 'Stop'
Push-Location $PSScriptRoot
$previousPath = $env:PATH
try {
    $env:PATH = (Split-Path $Compiler) + ";" + $previousPath
    $env:SOURCE_DATE_EPOCH = '1793491200'
    & $Compiler -O2 -std=gnu11 -static '-Wl,--no-insert-timestamp' -Icompat/include -I. -include compat/bw_posix_compat.h main.c disc_import.c compat/bw_posix_compat.c -lbcrypt -o bluewake-import.exe
    if ($LASTEXITCODE -ne 0) { throw 'BlueWake importer compilation failed.' }
} finally { $env:PATH = $previousPath; Pop-Location }

#include "disc_import.h"
#include <direct.h>
#include <io.h>
