#include <string.h>

static void report(void *context, double fraction, const char *stage) {
    (void)context;
    (void)stage;
    printf("%.6f\n", fraction);
    fflush(stdout);
}

static int verify_outputs(const char *output) {
    char path[512];
    snprintf(path, sizeof path, "%s/main.dol", output);
    FILE *dol = fopen(path, "rb");
    if (!dol) return 0;
    int valid = _fseeki64(dol, 0, SEEK_END) == 0 && _ftelli64(dol) >= 256;
    fclose(dol);
    if (!valid) return 0;

    snprintf(path, sizeof path, "%s/rels/*", output);
    struct _finddata_t entry;
    intptr_t search = _findfirst(path, &entry);
    if (search == -1) return 0;
    unsigned count = 0;
    do {
        if (!strcmp(entry.name, ".") || !strcmp(entry.name, "..")) continue;
        size_t len = strlen(entry.name);
        if (entry.attrib & _A_SUBDIR || len < 5 ||
            strcmp(entry.name + len - 4, ".rel") != 0 || entry.size < 0x44 ||
            ++count > 415) {
            valid = 0;
            break;
        }
        snprintf(path, sizeof path, "%s/rels/%s", output, entry.name);
        FILE *rel = fopen(path, "rb");
        if (!rel) {
            valid = 0;
            break;
        }
        unsigned char align[4];
        valid = fseek(rel, 0x40, SEEK_SET) == 0 &&
            fread(align, 1, sizeof align, rel) == sizeof align &&
            !memcmp(align, "\0\0\0\4", sizeof align);
        fclose(rel);
    } while (valid && _findnext(search, &entry) == 0);
    _findclose(search);
    return valid && count == 415;
}

int main(int argc, char **argv) {
    char error[512] = {0};
    if (argc != 3 || strlen(argv[2]) > 180) return 2;
    FILE *disc = fopen(argv[1], "rb");
    if (!disc) return 2;
    unsigned char header[8];
    int valid = fread(header, 1, sizeof header, disc) == sizeof header
        && memcmp(header, "GZLE01\0\0", sizeof header) == 0
        && _fseeki64(disc, 0, SEEK_END) == 0
        && _ftelli64(disc) == 1459978240LL;
    fclose(disc);
    if (!valid) {
        fputs("Expected a full-size GZLE01 revision 0 disc image.\n", stderr);
        return 1;
    }
    if (_mkdir(argv[2]) != 0) return 2;
    int result = bluewake_disc_prepare(argv[1], argv[2], report, NULL, NULL, NULL,
                                      error, sizeof error);
    if (result != 0) fprintf(stderr, "%s\n", error);
    if (result != 0) return 1;
    if (!verify_outputs(argv[2])) {
        fputs("Incomplete BlueWake output.\n", stderr);
        return 1;
    }
    return 0;
}

